  "relations": [
    {
      "from": "shipments",
      "to": "tracking_checkpoints",
      "type": "1:N",
      "label": "轨迹节点",
      "color": "#1976D2"
    },
    {
      "from": "carriers",
      "to": "shipments",
      "type": "1:N",
      "label": "承运",
      "color": "#43A047"
    },
    {
      "from": "tracking_platforms",
      "to": "shipments",
      "type": "1:N",
      "label": "路由到平台",
      "color": "#43A047",
      "style": "dashed"
    },
    {
      "from": "tracking_platforms",
      "to": "platform_carrier_mappings",
      "type": "1:N",
      "label": "映射的承运商",
      "color": "#43A047"
    },
    {
      "from": "carriers",
      "to": "platform_carrier_mappings",
      "type": "1:N",
      "label": "在多平台的代码",
      "color": "#43A047"
    },
    {
      "from": "tracking_platforms",
      "to": "status_mappings",
      "type": "1:N",
      "label": "状态映射",
      "color": "#43A047"
    },
    {
      "from": "shipments",
      "to": "message_logs",
      "type": "1:N",
      "label": "消息记录",
      "color": "#8E24AA"
    },
    {
      "from": "message_logs",
      "to": "message_logs",
      "type": "1:N",
      "label": "触发(triggered_by)",
      "color": "#8E24AA",
      "style": "dashed"
    }
  ],
  "design_rules": {
    "service_positioning": "系统定位为内部物流信息获取服务平台，为其他业务系统提供标准化物流信息查询服务。运单通过 API 注册，不直接关联订单实体",
    "unified_shipments": "shipments 统一管理国内/国际运单，不再区分。系统根据承运商→追踪平台映射自动路由到对应平台(AfterShip/快递100)",
    "carrier_split": "同一物流公司如同时有国内外服务则拆成独立承运商记录（如顺丰国内 sf-domestic / 顺丰国际 sf-international），不使用 scope 字段",
    "status_mapping_universal": "status_mappings 不再限制平台类型。每行对应一个 subtag/statusCode 级别映射。AfterShip 的 subtag 始终存在（无具体 subtag 时 fallback 到 _001 变体），因此只需一个 display_i18n_key 字段",
    "status_mapping_lookup": "查找顺序：先精确匹配 platform_status_code + platform_sub_code，匹配不到则 fallback 到仅 platform_status_code 的行",
    "i18n_optional": "display_i18n_key 仅国际平台(AfterShip)使用，对应 subtag 级别。国内平台(快递100)该字段为 NULL，前台轨迹文案直接使用原始 message 字段",
    "message_log_directions": "message_logs.direction 四种值：inbound_api(业务系统→Looply)、outbound_platform(Looply→物流平台)、inbound_webhook(物流平台→Looply)、outbound_push(Looply→业务系统)",
    "message_chain": "message_logs.triggered_by 建立消息因果链：业务系统请求 → 触发 Looply请求物流平台；物流平台Webhook回调 → 触发 推送业务系统消息",
    "checkpoint_mapping": "tracking_checkpoints 接收 Webhook 时立即完成状态映射，存储 mapped_internal_status。国际段额外存储 display_i18n_key，国内段该字段为 NULL",
    "encryption": "API Key/Secret 字段必须加密存储（AES-256）",
    "webhook_dedup": "tracking_checkpoints 通过联合唯一索引 (shipment_id, checkpoint_time, platform_tag, message) 去重",
    "platform_routing": "运单注册时根据 carrier_id → platform_carrier_mappings → tracking_platform_id 自动路由到对应追踪平台",
    "courier_redirect_link": "AfterShip 推送中包含 courier_redirect_link（承运商轨迹跳转链接），Looply 在状态通知中透传给业务系统，供用户端跳转查看承运商官方轨迹页面",
    "record_status_lifecycle": "shipments.record_status 管理记录生命周期(active/cancelled)，与 internal_status(物流状态) 语义独立。运单号录错或业务方主动取消时标记 cancelled，保留审计轨迹",
    "cancel_reason_enum": "cancel_reason 枚举值：tracking_no_error(运单号录错) / business_cancelled(业务方主动取消)，后续可扩展",
    "tracking_no_immutable": "tracking_no 不可变（行业标准），录错只能 DELETE + 重新 CREATE，旧记录标记 cancelled 保留审计",
    "carrier_change_no_limit": "承运商修改不限次数，每次 PATCH carrier_id 时同步切换追踪平台、更新 platform_tracking_id、清除旧轨迹节点",
    "platform_tracking_id": "platform_tracking_id 记录追踪平台内部ID（如 AfterShip tracking ID），承运商切换时随之更新",
    "tracking_url_template": "carriers.tracking_url_template 存储承运商官方轨迹页URL模板，使用 {tracking_no} 占位符，API 返回时拼接实际运单号",
    "one_to_one_tracking": "一个 tracking_no = 一个 business_order_no = 一条 shipment 记录（1:1 关系），不支持合单发货和多模块共享运单",
    "tracking_health": "tracking_health 标记追踪系统是否正常工作（normal/abnormal），用于后台监控，不影响用户端展示。物流异常（AttemptFail/Exception）不是追踪异常，tracking_health 仍为 normal",
    "tracking_health_enum": "tracking_health 枚举值：normal(追踪正常) / abnormal(追踪异常)。仅 Pending_002/004/005/006 和 Expired_001 触发 abnormal。后台监控根据此字段告警，但不通知业务系统",
    "status_mapping_strategy": "状态映射采用\"用户端简化+技术端精确\"策略：Pending_002/004/005/006 在 internal_status 映射为\"待揽收\"（用户视角），但通过 tracking_health 标记为 abnormal（技术视角），避免用户端看到技术性的\"追踪异常\"状态"
  }
}
